// SPDX-License-Identifier: LGPL-3.0-or-later
// Part of akantu-rs, a Rust port of Akantu (EPFL/LSMS). Differential tests of
// CouplerSolidContact (CPL-001/002, coupler_solid_contact_tmpl.hh) against
// the oracle fixtures fixtures/model/contact/explicit_* generated by
// oracle/probes/contact/contact_probe.cc through upstream's
// CouplerSolidContact (initFull, setTimeStep, solveStep): the same
// trajectories replayed through the port's coupler, bitwise (per-step
// SHA-256 digests of the displacement and the contact force, checkpoints,
// final stresses), with the contact switches of the contact replay (UD-002
// assembly, UD-365 trial slip; the friction case is generated on the UD-001
// zero-init variant).

#![allow(clippy::needless_range_loop)] // step/entry indices mirror the upstream test loops

mod common;

use akantu_contact::{ContactUpstreamCompat, PhysicalSurfaceSelector};
use akantu_core::enums::{AnalysisMethod, SpatialDirection};
use akantu_core::{ElementType, GhostType, Real};
use akantu_couplers::CouplerSolidContact;
use akantu_mesh::SharedMesh;
use akantu_model::ModelOptions;
use akantu_model::boundary_condition::FixedValue;
use akantu_model::constitutive_law::ElementDataSelector;
use akantu_parser::Parser;
use common::*;

#[test]
fn coupler_solid_contact_explicit_fixtures() {
    let all = cases("model/contact", "explicit_");
    assert!(!all.is_empty(), "no fixtures/model/contact/explicit_* case");
    for f in all {
        let c = f.case_id().to_owned();
        let friction = c.ends_with("explicit_friction");
        let mesh = read_mesh(&f.input_path("mesh").unwrap(), 2);
        let dat = read_input_text(&f, "material");
        let parser = Parser::parse_str(&dat, "material.dat").unwrap();
        let selector = PhysicalSurfaceSelector::new(&mesh, &parser).unwrap();
        let shared = SharedMesh::new(mesh);
        let mut coupler =
            CouplerSolidContact::with_parser(shared, None, "coupler_solid_contact", parser)
                .unwrap();
        coupler
            .solid
            .set_material_selector(Box::new(ElementDataSelector::new("physical_names")));
        coupler
            .init_full(&ModelOptions::new(AnalysisMethod::ExplicitLumpedMass))
            .unwrap();
        coupler
            .contact
            .set_surface_selector(Box::new(selector))
            .unwrap();
        coupler.contact.set_upstream_compat(ContactUpstreamCompat {
            assembly: true,
            trial_slip_on_previous_element: true,
            ..ContactUpstreamCompat::default()
        });
        let x = |v: Real| FixedValue {
            value: v,
            axis: SpatialDirection::X,
        };
        let y = |v: Real| FixedValue {
            value: v,
            axis: SpatialDirection::Y,
        };
        if friction {
            coupler.apply_dirichlet_bc(&x(0.0), "lower").unwrap();
            coupler.apply_dirichlet_bc(&y(0.0), "lower").unwrap();
        } else {
            coupler.apply_dirichlet_bc(&x(0.0), "upper").unwrap();
            coupler.apply_dirichlet_bc(&x(0.0), "lower").unwrap();
        }
        // the probe sets 0.05 × the stable time step; check the coupler's
        // stable time step reproduces it, then use the recorded value
        let dt = f64s(&f, "time_step")[0];
        assert_bits(
            &c,
            "time_step",
            &[coupler.stable_time_step().unwrap() * 0.05],
            &[dt],
        );
        coupler.set_time_step(dt, None).unwrap();
        let normal = f64s(&f, "schedule/normal");
        let shear = if friction {
            f64s(&f, "schedule/shear")
        } else {
            Vec::new()
        };
        let normal_steps = normal.len() - 1;
        let total = normal_steps + shear.len().saturating_sub(1);
        let digests = read_input_text(&f, "digests");
        let mut lines = digests.lines();
        let nb_contacts = i64s(&f, "nb_contact_elements");
        let mut compared = 0usize;
        for s in 0..total {
            if friction {
                if s < normal_steps {
                    coupler
                        .apply_dirichlet_bc(&y(-normal[s]), "loading")
                        .unwrap();
                } else {
                    coupler
                        .apply_dirichlet_bc(&x(shear[s - normal_steps]), "loading")
                        .unwrap();
                }
            } else {
                coupler
                    .apply_dirichlet_bc(&y(-normal[s]), "loading")
                    .unwrap();
                coupler.apply_dirichlet_bc(&y(normal[s]), "fixed").unwrap();
            }
            coupler.solve_step(None).unwrap();
            // damping of the velocities in contact (upstream test loop)
            let gaps = coupler.contact.gaps().as_slice().to_vec();
            let mut v = coupler.solid.velocity_mut().unwrap();
            for (g, vel) in gaps.iter().zip(v.as_mut_slice().as_chunks_mut::<2>().0) {
                if *g > 0.0 {
                    for vi in vel {
                        *vi *= 0.99;
                    }
                }
            }
            drop(v);
            assert_eq!(
                coupler.contact.contact_elements().len() as i64,
                nb_contacts[s],
                "{c}: step {s} contacts"
            );
            let step = s.to_string();
            let recorded = lines
                .clone()
                .next()
                .filter(|l| l.split(' ').next() == Some(step.as_str()));
            if let Some(line) = recorded {
                lines.next();
                let expected = format!(
                    "{s} {} {}",
                    sha_hex(coupler.displacement().unwrap().as_slice()),
                    sha_hex(coupler.contact.internal_force().as_slice())
                );
                compared += 1;
                if line != expected {
                    let ck = format!("step_{s}/displacement");
                    if f.quantity(&ck).is_ok() {
                        assert_bits(
                            &c,
                            &ck,
                            coupler.displacement().unwrap().as_slice(),
                            &f64s(&f, &ck),
                        );
                    }
                    panic!(
                        "{c}: step {s}: digest mismatch\n  got      {expected}\n  expected {line}"
                    );
                }
            }
            let ck = format!("step_{s}");
            if f.quantity(&format!("{ck}/displacement")).is_ok() {
                for (what, got) in [
                    ("velocity", coupler.solid.velocity().unwrap().as_slice()),
                    (
                        "acceleration",
                        coupler.solid.acceleration().unwrap().as_slice(),
                    ),
                    ("contact_force", coupler.contact.internal_force().as_slice()),
                    ("gaps", coupler.contact.gaps().as_slice()),
                    ("areas", coupler.contact.nodal_area().as_slice()),
                    (
                        "tangential_tractions",
                        coupler.contact.tangential_tractions().as_slice(),
                    ),
                ] {
                    let name = format!("{ck}/{what}");
                    assert_bits(&c, &name, got, &f64s(&f, &name));
                }
            }
        }
        assert!(compared > 0, "{c}: no digest compared");
        let mat = coupler.solid.material_by_name("upper").unwrap();
        let stress = mat
            .base()
            .stress
            .get(ElementType::Quadrangle4, GhostType::NotGhost)
            .unwrap();
        assert_bits(
            &c,
            "final/stress_upper",
            stress.as_slice(),
            &f64s(&f, "final/stress_upper"),
        );
        // upstream getContactForce() is the solid's internal force (UD-623)
        assert_bits(
            &c,
            "getContactForce",
            coupler.contact_force().unwrap().as_slice(),
            coupler.solid.internal_force().unwrap().as_slice(),
        );
        eprintln!("{c}: {total} steps, {compared} digests bitwise");
    }
}
